            "time": {
              "type": "string",
              "description": "第三条历史包裹更新时间",
              "sampleValue": "周一 16:30"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/courier_box.png",
      "description": "彩色快递箱子图标，适合物流信息、取件提醒和包裹状态识别。",
      "bindTo": "/data/assets/parcelIcon"
    }
  ]
}

